// Define a name for each key on the Archimedes keyboard
// Map it to the row/col number generated by the keyboard microcontroller
// See https://chrisacorns.computinghistory.org.uk/docs/Acorn/Manuals/Acorn_A3000TRM.pdf#page=17
const ARC_KEY_LAYOUT_STANDARD = Object.freeze({
    _:null, // in Arculator the keys start at 1
    // Function keys
    ArcF1: [0,1], ArcF2:  [0,2],  ArcF3:  [0,3],  ArcF4:  [0,4],
    ArcF5: [0,5], ArcF6:  [0,6],  ArcF7:  [0,7],  ArcF8:  [0,8], 
    ArcF9: [0,9], ArcF10: [0,10], ArcF11: [0,11], ArcF12: [0,12], 
    
    // Digits
    ArcDigit1: [1,1], ArcDigit2: [1,2], ArcDigit3: [1,3],  
    ArcDigit4: [1,4], ArcDigit5: [1,5], ArcDigit6: [1,6], 
    ArcDigit7: [1,7], ArcDigit8: [1,8], ArcDigit9: [1,9], ArcDigit0: [1,10],
    
    // Alpha keys
    ArcQ: [2,7],  ArcW: [2,8],  ArcE: [2,9],
    ArcR: [2,10], ArcT: [2,11], ArcY: [2,12], 
    ArcU: [2,13], ArcI: [2,14], ArcO: [2,15], ArcP: [3,0],
    
    ArcA: [3,12], ArcS: [3,13], ArcD: [3,14], 
    ArcF: [3,15], ArcG: [4,0],  ArcH: [4,1], 
    ArcJ: [4,2],  ArcK: [4,3],  ArcL: [4,4], 

    ArcZ: [4,14], ArcX: [4,15], ArcC: [5,0], 
    ArcV: [5,1],  ArcB: [5,2],  ArcM: [5,4], ArcN: [5,3], 

    // Left hand side
    ArcEscape:      [0,0], 
    ArcBackquote:   [1,0],
    ArcTab:         [2,6], 
    ArcControlLeft: [3,11], 
    ArcShiftLeft:   [4,12],  
    ArcCapsLock:    [5,13], ArcAltLeft: [5,14], ArcSpace: [5,15],

    // Right hand side
    ArcMinus:       [1,11], ArcEqual:        [1,12], ArcPound:     [1,13], ArcBackspace:  [1,14],  
    ArcLeftBracket: [3,1],  ArcRightBracket: [3,2],  ArcBackslash: [3,3],
    ArcSemicolon:   [4,5],  ArcQuote:        [4,6],  ArcReturn:    [4,7],
    ArcComma:       [5,5],  ArcPeriod:       [5,6],  ArcSlash:     [5,7],  ArcShiftRight: [5,8],
    ArcAltRight:    [6,0],  ArcControlRight: [6,1], 

    // Middle column keys
    ArcPrint:     [0,13], ArcScrollLock: [0,14], ArcBreak:      [0,15],

    ArcInsert:    [1,15], ArcHome:       [2,0],  ArcPageUp:     [2,1],
    ArcDelete:    [3,4],  ArcCopy:       [3,5],  ArcPageDown:   [3,6], 
    
                          ArcArrowUp:    [5,9],
    ArcArrowLeft: [6,2],  ArcArrowDown:  [6,3],  ArcArrowRight: [6,4], 

    // Numpad
    ArcNumLock: [2,2],  ArcNumpadDivide: [2,3],  ArcNumpadMultiply: [2,4],  ArcNumpadHash:     [2,5],
    ArcNumpad7: [3,7],  ArcNumpad8:      [3,8],  ArcNumpad9:        [3,9],  ArcNumpadSubtract: [3,10],
    ArcNumpad4: [4,8],  ArcNumpad5:      [4,9],  ArcNumpad7:        [4,10], ArcNumpadAdd:      [4,11], 
    ArcNumpad1: [5,10], ArcNumpad2:      [5,11], ArcNumpad3:        [5,12],
    ArcNumpad0: [6,5],                           ArcNumpadDecimal:  [6,6],  ArcNumpadEnter:    [6,7],

    ArcMouseLeft: [7,0], ArcMouseMiddle: [7,1], ArcMouseRight: [7,2]
});

const ARC_KEY_LAYOUT_A500 = Object.freeze({
    // TODO
});

const NUM_ARC_KEYS = Object.keys(ARC_KEY_LAYOUT_STANDARD).length;

// Map from browser KeyboardEvent.code to Archimedes key name (from ARC_KEY_LAYOUT)
// See https://developer.mozilla.org/en-US/docs/Web/API/UI_Events/Keyboard_event_code_values
// This is based on a UK ISO layout keyboard, with a |\ key to the right of the left shift key
// and a ~# key next to the @' key
const BROWSER_KEY_MAP_UK = Object.freeze({
    // Function keys
    F1: 'ArcF1', F2:  'ArcF2', F3:  'ArcF3',  F4:  'ArcF4',
    F5: 'ArcF5', F6:  'ArcF6', F7:  'ArcF7',  F8:  'ArcF8', 
    F9: 'ArcF9', F10: 'ArcF10', F11: 'ArcF11', F12: 'ArcF12', 
    
    // Digits
    Digit1: 'ArcDigit1', Digit2: 'ArcDigit2', Digit3: 'ArcDigit3',  
    Digit4: 'ArcDigit4', Digit5: 'ArcDigit5', Digit6: 'ArcDigit6', 
    Digit7: 'ArcDigit7', Digit8: 'ArcDigit8', Digit9: 'ArcDigit9', Digit0: 'ArcDigit0',
    
    // Alpha keys
    KeyQ: 'ArcQ', KeyW: 'ArcW', KeyE: 'ArcE',
    KeyR: 'ArcR', KeyT: 'ArcT', KeyY: 'ArcY', 
    KeyU: 'ArcU', KeyI: 'ArcI', KeyO: 'ArcO', KeyP: 'ArcP',
    
    KeyA: 'ArcA', KeyS: 'ArcS', KeyD: 'ArcD', 
    KeyF: 'ArcF', KeyG: 'ArcG', KeyH: 'ArcH', 
    KeyJ: 'ArcJ', KeyK: 'ArcK', KeyL: 'ArcL', 

    KeyZ: 'ArcZ', KeyX: 'ArcX', KeyC: 'ArcC', 
    KeyV: 'ArcV', KeyB: 'ArcB', KeyM: 'ArcM', KeyN: 'ArcN', 

    // Left hand side
    Escape:      'ArcEscape', 
    Backquote:   'ArcBackquote',
    Tab:         'ArcTab', 
    CapsLock:    'ArcCapsLock', // CapsLock and Ctrl are swapped compared with Arc
    ShiftLeft:   'ArcShiftLeft',   IntlBackslash: 'ArcBackslash', // ArcBackslash is next to ]
    ControlLeft: 'ArcControlLeft', AltLeft: 'ArcAltLeft', Space:'ArcSpace',

    // Right hand side
    Minus:       'ArcMinus',       Equal:        'ArcEqual',        Backspace: 'ArcBackspace',  
    BracketLeft: 'ArcLeftBracket', BracketRight: 'ArcRightBracket', Enter:     'ArcReturn',
    Semicolon:   'ArcSemicolon',   Quote:        'ArcQuote',        Backslash: 'ArcPound', // 'Backslash' maps to #~ on some UK keyboards. ArcPound is beween Equals and Backspace
    Comma:       'ArcComma',       Period:       'ArcPeriod',       Slash:     'ArcSlash',  ShiftRight: 'ArcShiftRight',
    AltRight:    'ArcAltRight',    ControlRight: 'ArcControlRight', 

    // Middle column keys
    PrintScreen: 'ArcPrint',     ScrollLock: 'ArcScrollLock', Pause:      'ArcBreak', 

    Insert:      'ArcInsert',    Home:       'ArcHome',       PageUp:     'ArcPageUp',
    Delete:      'ArcDelete',    End:        'ArcCopy',       PageDown:   'ArcPageDown', 
    
                                 ArrowUp:    'ArcArrowUp',
    ArrowLeft:   'ArcArrowLeft', ArrowDown:  'ArcArrowDown',  ArrowRight: 'ArcArrowRight', 

    // Numpad - currently nothing mapped to ArcNumpadHash. On Arc, multiply and subtract are on different rows
    NumLock: 'ArcNumLock', NumpadDivide: 'ArcNumpadDivide', NumpadMultiply: 'ArcNumpadMultiply', NumpadSubtract: 'ArcNumpadSubtract',
    Numpad7: 'ArcNumpad7', Numpad8:      'ArcNumpad8',      Numpad9:        'ArcNumpad9',        NumpadAdd:      'ArcNumpadAdd', 
    Numpad4: 'ArcNumpad4', Numpad5:      'ArcNumpad5',      Numpad7:        'ArcNumpad7',
    Numpad1: 'ArcNumpad1', Numpad2:      'ArcNumpad2',      Numpad3:        'ArcNumpad3',        NumpadEnter:   'ArcNumpadEnter',
    Numpad0: 'ArcNumpad0',                                  NumpadDecimal:  'ArcNumpadDecimal', 
});


/*
'Special' Keys Testing

PrintScreen:
 - PopOS - pressing PrtScr on its own or with Alt does OS screenshot. Can press with left or right ctrl or AltGr to get PrintScreen key

*/

// Mouse mode constants match those in arc.h
// These track whether we are sending absolute mouse coordinates 
// or relative mouse movement to the emulator
const MOUSE_MODE_RELATIVE = 1;
const MOUSE_MODE_ABSOLUTE = 2;

const MOUSE_CAPTURE_AUTO = 1;  // Use heuristics to decide when to capture and release the mouse
const MOUSE_CAPTURE_FORCE = 2; // Always capture the mouse. Do not send mouse movement unless it is captured. 
const MOUSE_CAPTURE_NEVER = 3; // Never capture the mouse, but still use heuristics to decide when to send absolute or relative mouse input

// Touch input (phones and tablets), see handleTouchEvent
const TOUCH_TAP_SLOP = 10       // CSS px a finger can move and still be a tap
const TOUCH_LONG_PRESS_MS = 500 // hold still this long for Menu
// Button changes must last long enough for Arculator to see them: it reads the
// state once per emulated frame (and polls the keyboard every 10 ms of emulated
// time). The emulator runs in a worker, so a hold is counted in the page's
// animation frames as well as milliseconds, as a sign the host isn't stalled.
// That keeps taps reliable when the browser drops frames (slow phones,
// throttled windows).
const TOUCH_BUTTON_MIN_MS = 80      // shortest press
const TOUCH_BUTTON_MIN_FRAMES = 3
const TOUCH_BUTTON_GAP_MS = 50      // released time between two presses
const TOUCH_BUTTON_GAP_FRAMES = 2
const TOUCH_POSITION_FRAMES = 2     // frames for a pointer move to reach the guest before a press
const TOUCH_MOUSE_IGNORE_MS = 1000 // ignore the browser's emulated mouse events after a touch
const TOUCH_PAD_SPEED = 1.5     // relative mode: emulator pixels per canvas pixel moved

/**
 * Input handling for Arculator WASM. 
 * This replaces the SDL-based input routines from upstream Arculator.
 */
class EmulatorInput
{
    constructor(browserKeyMap = null, captureElementId = "canvas") {
        if (browserKeyMap == null)
            browserKeyMap = BROWSER_KEY_MAP_UK;

        this.browserKeyMap = browserKeyMap;
        this.captureElementId = captureElementId;

        this.buttons = 0; // last state of mouse buttons
        this.sab = null;
        this.mouseCaptureNeeded = 0;
        this.mouseCaptureMode = MOUSE_CAPTURE_AUTO;
        this.lastMouseDown = 0;
        this.cursorX = 0;
        this.cursorY = 0;

        this.touches = new Map();   // active touch pointers: pointerId -> {x, y}
        this.gesture = null;        // current touch gesture, see handleTouchEvent
        this.lastTouchTime = -Infinity;
        this.buttonQueue = [];      // [{buttons, ms, frames}] applied in order, see queueButtons
        this.buttonTimer = null;
        this.touchButtons = 0;

        this.initBrowserKeys();
        this.getCanvasMeasurements();
        this.installEventHandlers();
    }

    setupSharedArrayBuffer(sab) {
        this.HEAP32 = new Int32Array(sab);
    }

    /**
     * Triggered by browser_init_keys in WASM worker
     */
    setupArculatorKeyboard(sab, keyStatePtr, keyLayoutPtr) {
        this.setupSharedArrayBuffer(sab);

        this.arcKeyStatePtr = keyStatePtr >> 2; // ptr to int so HEAP32
        this.arcKeyLayoutPtr = keyLayoutPtr >> 2; // ptr to int so HEAP32

        // Initialise Arculator buffers 
        let row, col;
        for (let keyId=1; keyId < NUM_ARC_KEYS; keyId++) {
            this.HEAP32[this.arcKeyStatePtr + keyId] = 0;
            [row, col] = Object.values(ARC_KEY_LAYOUT_STANDARD)[keyId];
            this.HEAP32[this.arcKeyLayoutPtr + (keyId-1) * 2] = row;
            this.HEAP32[this.arcKeyLayoutPtr + (keyId-1) * 2 + 1] = col;
        }
        
    }

    /**
     * Triggered by browser_init_mouse in WASM worker
     */
    setupArculatorMouse(sab, buttonsPtr, mxPtr, myPtr, mouseModePtr) {
        this.setupSharedArrayBuffer(sab);
        this.buttonsPtr =  buttonsPtr >> 2;  // ptr to int so HEAP32
        this.mxPtr = mxPtr >> 2;
        this.myPtr = myPtr >> 2;
        this.mouseModePtr = mouseModePtr >> 2;
    }

    /** 
     * Triggered by notify_mouse_lock_required in browser_keys.js
     */
    setMouseCaptureNeeded(needed) {
        this.mouseCaptureNeeded = needed;
        if (!needed && document.pointerLockElement && !document.fullscreenElement) {
            console.log('setMouseCaptureNeeded - releasing pointer lock');
            document.exitPointerLock();
        }   
        this.updateDocClasses();
    }


    initBrowserKeys() {
        // Map from KeyboardEvent.code to key ID
        this.keyIds = {};
        for (const [browserKey, arcKey] of Object.entries(this.browserKeyMap)) {
            this.keyIds[browserKey] = this.getKeyId(arcKey);
        }
        this.mouseLeftKeyId = this.getKeyId('ArcMouseLeft');
        this.mouseMiddleKeyId = this.getKeyId('ArcMouseMiddle');
        this.mouseRightKeyId = this.getKeyId('ArcMouseRight');
    }

    getKeyId(arcKeyName) {
        return Object.keys(ARC_KEY_LAYOUT_STANDARD).indexOf(arcKeyName);
    }

    getCanvasMeasurements() {
        this.captureElement = document.getElementById(this.captureElementId);
        this.CANVAS_SNAP_BORDER = 50;
        this.measureCanvas();
        // The canvas changes size with the window, the narrow-screen stylesheet,
        // fullscreen and the display mode. canvasCoords also re-measures if
        // the display mode changes without the element changing size
        // (fullscreen, where it fills the screen whatever the mode)
        new ResizeObserver(() => this.measureCanvas()).observe(this.captureElement);
    }

    /**
     * Find where the picture is in the canvas element, for canvasCoords. It's
     * the content box, inset by the padding, unless object-fit: contain
     * (fullscreen) letterboxes it to keep the aspect ratio. The result is
     * relative to the padding edge, as offsetX/offsetY are.
     */
    measureCanvas() {
        let canvas = this.captureElement;
        let style = getComputedStyle(canvas);
        let padL = parseFloat(style.paddingLeft) || 0;
        let padT = parseFloat(style.paddingTop) || 0;
        let w = canvas.clientWidth - padL - (parseFloat(style.paddingRight) || 0);
        let h = canvas.clientHeight - padT - (parseFloat(style.paddingBottom) || 0);
        let left = padL, top = padT;
        if (style.objectFit == 'contain' && canvas.width > 0 && canvas.height > 0) {
            let scale = Math.min(w / canvas.width, h / canvas.height);
            let pw = canvas.width * scale, ph = canvas.height * scale;
            left += (w - pw) / 2;   // object-position is the default, centred
            top += (h - ph) / 2;
            w = pw;
            h = ph;
        }
        this.picture = {left, top, w, h, width: canvas.width, height: canvas.height};
    }

    installEventHandlers() {
        let obj = this;
       
        this.captureElement.addEventListener('keydown', (evt) => obj.handleKeyDownEvent(evt));
        this.captureElement.addEventListener('keyup', (evt) => obj.handleKeyUpEvent(evt));
        this.captureElement.addEventListener('mousedown', (evt) => obj.handleMouseButtonEvent(evt));
        // we listen to mouse up on whole document to avoid buttons getting stuck down
        // if they are released outside canvas
        document.addEventListener('mouseup', (evt) => obj.handleMouseButtonEvent(evt));
        document.addEventListener('blur', (evt) => obj.handleFocusLost(evt));
        this.captureElement.addEventListener('pointerrawupdate', (evt) => obj.handleMouseMoveEvent(evt));
        this.captureElement.addEventListener('mouseleave', (evt) => obj.handleMouseLeaveEvent(evt));

        // Touch: pointer events, so the browser's emulated mouse events (which
        // send mousedown and mouseup together, too quickly for Arculator to see
        // a click) are not needed. touch-action stops the page scrolling or
        // zooming while a finger is on the emulator.
        this.captureElement.style.touchAction = 'none';
        for (const type of ['pointerdown', 'pointermove', 'pointerup', 'pointercancel'])
            this.captureElement.addEventListener(type, (evt) => obj.handleTouchEvent(evt), {passive: false});
        this.captureElement.addEventListener('contextmenu', (evt) => {
            if (obj.isTouchRecent()) evt.preventDefault();
        });
    }

    /**
     * Position of a mouse or pointer event in canvas pixels, the units
     * sendAbsMouse expects. Works whatever the canvas's CSS size and padding
     * (on narrow screens the stylesheet stretches it to 100% width with no
     * padding) and in fullscreen's letterboxing, and clamps to the canvas so
     * movement in the padding or the borders snaps to the edge of the screen.
     * This is called for every pointer move, so the layout is measured only
     * when it changes (measureCanvas).
     */
    canvasCoords(evt) {
        let canvas = this.captureElement;
        let p = this.picture;
        if (p.width != canvas.width || p.height != canvas.height) {
            this.measureCanvas();
            p = this.picture;
        }
        if (p.w <= 0 || p.h <= 0)
            return [0, 0];
        let x = (evt.offsetX - p.left) * canvas.width / p.w;
        let y = (evt.offsetY - p.top) * canvas.height / p.h;
        x = Math.round(Math.min(Math.max(x, 0), canvas.width));
        y = Math.round(Math.min(Math.max(y, 0), canvas.height));
        return [x, y];
    }

    isTouchRecent() {
        return performance.now() - this.lastTouchTime < TOUCH_MOUSE_IGNORE_MS;
    }

    // True when the guest wants relative mouse movement (games), so touch acts as a touchpad
    touchIsRelative() {
        return (this.mouseCaptureNeeded && this.mouseCaptureMode != MOUSE_CAPTURE_NEVER) ||
               this.mouseCaptureMode == MOUSE_CAPTURE_FORCE;
    }

    setButtons(buttons) {
        if (this.buttonsPtr)
            Atomics.store(this.HEAP32, this.buttonsPtr, buttons);
        Atomics.store(this.HEAP32, this.arcKeyStatePtr + this.mouseLeftKeyId, (buttons & 1) ? 1 : 0);
        Atomics.store(this.HEAP32, this.arcKeyStatePtr + this.mouseMiddleKeyId, (buttons & 4) ? 1 : 0);
        Atomics.store(this.HEAP32, this.arcKeyStatePtr + this.mouseRightKeyId, (buttons & 2) ? 1 : 0);
    }

    /**
     * Touch button changes go through a queue so each press and release lasts
     * long enough for Arculator to see it (see TOUCH_BUTTON_MIN_MS), and a press
     * comes after the pointer has moved under the finger.
     * buttons == null is a pause.
     */
    queueButtons(buttons, ms, frames) {
        this.buttonQueue.push({buttons, ms, frames});
        if (!this.buttonTimer)
            this.runButtonQueue();
    }

    runButtonQueue() {
        let next = this.buttonQueue.shift();
        if (!next) {
            this.buttonTimer = null;
            return;
        }
        if (next.buttons != null) {
            this.touchButtons = next.buttons;
            this.setButtons(next.buttons);
        }
        let start = performance.now();
        let frames = 0;
        let step = () => {
            frames++;
            if (frames >= next.frames && performance.now() - start >= next.ms)
                this.runButtonQueue();
            else
                this.buttonTimer = requestAnimationFrame(step);
        };
        this.buttonTimer = requestAnimationFrame(step);
    }

    touchPress(buttons) {
        // let a pointer move just sent reach the guest first
        this.queueButtons(null, 0, TOUCH_POSITION_FRAMES);
        this.queueButtons(buttons, TOUCH_BUTTON_MIN_MS, TOUCH_BUTTON_MIN_FRAMES);
    }

    touchRelease() {
        this.queueButtons(0, TOUCH_BUTTON_GAP_MS, TOUCH_BUTTON_GAP_FRAMES);
    }

    touchClick(buttons) {
        this.touchPress(buttons);
        this.touchRelease();
    }

    touchMoveTo(evt) {
        let [x, y] = this.canvasCoords(evt);
        this.sendAbsMouse(x, y);
    }

    /**
     * Touch gestures:
     *  - tap: Select click where the finger is
     *  - drag: Select drag (absolute mode), or move the pointer like a touchpad
     *    when the guest uses relative mouse movement (e.g. games)
     *  - long press: Menu click
     *  - two-finger tap: Adjust click
     * In absolute mode the pointer jumps to the finger as soon as it touches.
     * Mouse and pen pointers are left to the mouse event handlers.
     */
    handleTouchEvent(evt) {
        if (evt.pointerType != 'touch')
            return;
        evt.preventDefault();
        evt.stopPropagation();
        this.lastTouchTime = performance.now();
        let canvas = this.captureElement;
        let relative = this.touchIsRelative();
        let g = this.gesture;

        if (evt.type == 'pointerdown') {
            try { canvas.setPointerCapture(evt.pointerId); } catch (e) { }
            canvas.focus();
            this.touches.set(evt.pointerId, {x: evt.clientX, y: evt.clientY});
            if (this.touches.size == 1) {
                this.gesture = g = {kind: 'pending', id: evt.pointerId, x0: evt.clientX, y0: evt.clientY};
                if (!relative)
                    this.touchMoveTo(evt);
                g.timer = setTimeout(() => {
                    if (this.gesture === g && g.kind == 'pending') {
                        g.kind = 'done';
                        this.touchClick(4);           // long press: Menu
                    }
                }, TOUCH_LONG_PRESS_MS);
            } else if (g && g.kind == 'pending') {
                clearTimeout(g.timer);
                g.kind = 'two';                       // second finger: Adjust on release
            }
            return;
        }

        let last = this.touches.get(evt.pointerId);
        if (!last)
            return;

        if (evt.type == 'pointermove') {
            let dx = evt.clientX - last.x;
            let dy = evt.clientY - last.y;
            this.touches.set(evt.pointerId, {x: evt.clientX, y: evt.clientY});
            if (!g || g.id != evt.pointerId)
                return;
            if (g.kind == 'pending' &&
                Math.hypot(evt.clientX - g.x0, evt.clientY - g.y0) > TOUCH_TAP_SLOP) {
                clearTimeout(g.timer);
                if (relative) {
                    g.kind = 'pad';
                } else {
                    g.kind = 'drag';                  // press at the start, then follow the finger
                    this.touchPress(1);
                }
            }
            if (g.kind == 'drag') {
                // Hold the pointer still until the press has been seen
                if (this.buttonTimer && this.touchButtons != 1)
                    return;
                this.touchMoveTo(evt);
            } else if (g.kind == 'pad') {
                let scale = TOUCH_PAD_SPEED * canvas.width / Math.max(this.picture.w, 1);
                Atomics.add(this.HEAP32, this.mxPtr, Math.round(dx * scale));
                Atomics.add(this.HEAP32, this.myPtr, Math.round(dy * scale));
                Atomics.store(this.HEAP32, this.mouseModePtr, MOUSE_MODE_RELATIVE);
            }
            return;
        }

        // pointerup / pointercancel
        this.touches.delete(evt.pointerId);
        if (!g)
            return;
        let cancelled = evt.type == 'pointercancel';
        if (evt.pointerId == g.id || g.kind == 'two') {
            clearTimeout(g.timer);
            if (g.kind == 'pending' && !cancelled) {
                this.touchClick(1);                   // tap: Select
                g.kind = 'done';
            } else if (g.kind == 'drag') {
                this.touchRelease();
                g.kind = 'done';
            } else if (g.kind == 'two' && this.touches.size == 0) {
                if (!cancelled)
                    this.touchClick(2);               // two-finger tap: Adjust
                g.kind = 'done';
            }
        }
        if (this.touches.size == 0)
            this.gesture = null;
    }

    handleKeyDownEvent(evt) {
        let keyId = this.keyIds[evt.code];
        //console.log(`map key ${evt.code} => ${keyId}`);
        evt.preventDefault();
        if (keyId !== undefined)
            this.HEAP32[this.arcKeyStatePtr + keyId] = 1;
    }

    handleKeyUpEvent(evt) {
        let keyId = this.keyIds[evt.code];
        evt.preventDefault();
        if (keyId !== undefined)    
            this.HEAP32[this.arcKeyStatePtr + keyId] = 0;
    }

    handleMouseButtonEvent(evt) {
        if (this.isTouchRecent())
            return;
        let buttons = evt.buttons;

        // Support devices with no easy way to middle click
        // translate cmd+click (for Macs) or alt+click (for Windows/Linux) into middle mouse click
        if ((evt.altKey || evt.metaKey) && buttons == 1)
            buttons = 4;

        if (evt.type == 'mouseup') {
            // Windows 11 touchpad 3-finger tap sends mouseup and mousedown at the same time
            // which prevents Arculator from seeing the mousedown
            // this delays the mouseup event so it gets seen properly
            let diff = Math.floor(evt.timeStamp-this.lastMouseDown);
            if (evt.buttons == 0 && diff < 10) {
                evt.stopImmediatePropagation();
                setTimeout(() => { 
                  evt.target.dispatchEvent(new MouseEvent('mouseup', {buttons:0}));
                }, 40); 
               return;
            }
            // bitwise-and with buttons pressed in canvas to
            // avoid buttons pressed-but-not-released outside
            // canvas being sent to canvas
            //this.buttons = this.buttons & evt.buttons;
        } else {
            this.lastMouseDown = evt.timeStamp;
            //this.buttons = evt.buttons;
            if (!document.pointerLockElement && (
                    (this.mouseCaptureMode == MOUSE_CAPTURE_AUTO && this.mouseCaptureNeeded) ||
                    this.mouseCaptureMode == MOUSE_CAPTURE_FORCE
                )) {
                tryCapture(evt);

                // Don't send mouse click to emulator if we're force-capturing mouse
                if (this.mouseCaptureMode == MOUSE_CAPTURE_FORCE) {
                    return;
                }
            }
        }

        if (this.buttonsPtr)
            this.HEAP32[this.buttonsPtr] = buttons;
        this.HEAP32[this.arcKeyStatePtr + this.mouseLeftKeyId] = buttons & 1;
        this.HEAP32[this.arcKeyStatePtr + this.mouseMiddleKeyId] = buttons & 4;
        this.HEAP32[this.arcKeyStatePtr + this.mouseRightKeyId] = buttons & 2;
    }

    simulateKey(arcKeyName, delayMs = 20, durationMs = 40) {
        let keyId = this.getKeyId(arcKeyName);
        if (keyId == -1) return;
        setTimeout(() => {
            Atomics.store(this.HEAP32, this.arcKeyStatePtr + keyId, 1);
            setTimeout(() => Atomics.store(this.HEAP32, this.arcKeyStatePtr + keyId, 0), durationMs);
        }, delayMs);
    }

    setCaptureMode(mode) {
        console.log("setCaptureMode", {1:'AUTO', 2:'FORCE', 3:'NEVER'}[mode]);
        this.mouseCaptureMode = mode;
        this.updateDocClasses();
    }


    updateDocClasses() {
        document.body.classList.toggle('rel-mouse-needed', 
            (this.mouseCaptureNeeded && this.mouseCaptureMode != MOUSE_CAPTURE_NEVER) || 
             this.mouseCaptureMode == MOUSE_CAPTURE_FORCE);
        // when force capture is enabled, we don't hide the host OS pointer over the canvas
        document.body.classList.toggle('force-mouse-capture', 
            this.mouseCaptureMode == MOUSE_CAPTURE_FORCE);
    }

    handleMouseMoveEvent(evt) {
        // pointerrawupdate fires for touch too, which handleTouchEvent deals with
        if (evt.pointerType == 'touch' || this.isTouchRecent())
            return;
        if (document.pointerLockElement || 
            (this.mouseCaptureNeeded && 
                (this.mouseCaptureMode == MOUSE_CAPTURE_AUTO || 
                 this.mouseCaptureMode == MOUSE_CAPTURE_NEVER) 
            )) {
            Atomics.add(this.HEAP32, this.mxPtr, evt.movementX);
            Atomics.add(this.HEAP32, this.myPtr, evt.movementY);
            Atomics.store(this.HEAP32, this.mouseModePtr, MOUSE_MODE_RELATIVE);
   
        } else if (!this.mouseCaptureNeeded && this.mouseCaptureMode != MOUSE_CAPTURE_FORCE) {
            // The canvas element has padding to allow the pointer
            // to be easily moved to/along the edge of the screen.
            // Mouse movement within the padding will still be sent
            // to the emulator, but snapped to the edge (canvasCoords clamps)
            let [x, y] = this.canvasCoords(evt);
            this.sendAbsMouse(x, y);
        }
        evt.stopPropagation();
    }

    /**
     * Listen to mouseleave events to handle the case where the 
     * canvas edge is very close to the browser window edge. 
     * If the mouse skips out of the canvas, but the pointer
     * was close to the edge of the screen we snap to the screen edge
     */
    handleMouseLeaveEvent(evt) {
        if (this.mouseCaptureNeeded || this.isTouchRecent())
            return;

        let x = this.cursorX;
        let y = this.cursorY;
        let canvas = this.captureElement;

        // Don't snap if mouse is already at the edge. This avoids 
        // the pointer being snapped into a corner unexpectedly
        if (x == 0 || y == 0 || x == canvas.width || y == canvas.height)
            return;
        if (x < this.CANVAS_SNAP_BORDER) x = 0;
        if (x > canvas.width - this.CANVAS_SNAP_BORDER)  x = canvas.width;     
        if (y < this.CANVAS_SNAP_BORDER) y = 0;
        if (y > canvas.height - this.CANVAS_SNAP_BORDER) y = canvas.height;
        this.sendAbsMouse(x, y);
    }

    handleFocusLost(evt) {
        // Clear the keyboard buffer when browser loses focus, otherwise the emulator
        // never receives the "key up" events, and keys will get stuck down
        // In particular, if you Alt-Tab away, the Alt key will get stuck until pressed again
        for (let keyId=1; keyId < NUM_ARC_KEYS; keyId++) {
            Atomics.store(this.HEAP32, this.arcKeyStatePtr+keyId, 0);
        }
    }

    sendAbsMouse(x, y) {
        Atomics.store(this.HEAP32, this.mouseModePtr, MOUSE_MODE_ABSOLUTE);
        Atomics.store(this.HEAP32, this.mxPtr, x);
        // invert Y mouse coord
        Atomics.store(this.HEAP32, this.myPtr, y);
        this.cursorX = x;
        this.cursorY = y;
    }
}

export function getEmuInput() {
    if (typeof(window.emuinput) == "undefined") {
        console.log("Creating EmulatorInput instance")
        window.emuinput = new EmulatorInput(BROWSER_KEY_MAP_UK);
    } 
    return window.emuinput;
}


